<?php
function oecrm_notice_sync_statuses($conn){mysqli_query($conn,"UPDATE notices SET status='published',published_at=COALESCE(published_at,NOW()) WHERE status='scheduled' AND publish_at<=NOW() AND (expires_at IS NULL OR expires_at>NOW())");mysqli_query($conn,"UPDATE notices SET status='expired' WHERE status IN ('published','scheduled') AND expires_at IS NOT NULL AND expires_at<=NOW()");}
function oecrm_employee_notices($conn,$employeeId,$limit=50){oecrm_notice_sync_statuses($conn);$sql="SELECT n.*,r.first_seen_at,r.read_at,r.acknowledged_at FROM notices n JOIN employeestbl e ON e.id=? LEFT JOIN notice_receipts r ON r.notice_id=n.id AND r.employee_id=e.id WHERE n.company_id=e.company_id AND n.status='published' AND n.publish_at<=NOW() AND (n.expires_at IS NULL OR n.expires_at>NOW()) AND (n.audience_type='all' OR (n.audience_type='department' AND EXISTS(SELECT 1 FROM notice_targets t WHERE t.notice_id=n.id AND t.department_id=e.department_id)) OR (n.audience_type='employee' AND EXISTS(SELECT 1 FROM notice_targets t WHERE t.notice_id=n.id AND t.employee_id=e.id))) ORDER BY FIELD(n.priority,'urgent','high','normal','low'),n.publish_at DESC LIMIT ".(int)$limit;$s=mysqli_prepare($conn,$sql);mysqli_stmt_bind_param($s,'i',$employeeId);mysqli_stmt_execute($s);return mysqli_stmt_get_result($s);}
function oecrm_notice_event($conn,$noticeId,$employeeId,$actorType,$actorId,$event,$details=''){$ip=$_SERVER['REMOTE_ADDR']??'';$s=mysqli_prepare($conn,'INSERT INTO notice_events(notice_id,employee_id,actor_type,actor_id,event_type,details,ip_address) VALUES(?,?,?,?,?,?,?)');mysqli_stmt_bind_param($s,'iisisss',$noticeId,$employeeId,$actorType,$actorId,$event,$details,$ip);mysqli_stmt_execute($s);mysqli_stmt_close($s);}
